namespace {

constexpr const char* kMainClassName = "__main__";
constexpr const char* kMainMethodName = "main";
constexpr const char* kReturnFormalName = "__return__";

[[noreturn]] void fail_with_msg(const string& msg, AST* node = nullptr) {
    if (node != nullptr && node->getPos() != nullptr) {
        cerr << "at position: " << node->getPos()->print() << endl;
    }
    cerr << "Error: " << msg << endl;
    exit(1);
}

Formal* make_return_formal(AST* owner, Type* return_type) {
    Pos* pos = nullptr;
    if (owner != nullptr && owner->getPos() != nullptr) {
        pos = owner->getPos()->clone();
    } else {
        pos = new Pos(0, 0, 0, 0);
    }
    IdExp* ret_id = new IdExp(pos->clone(), kReturnFormalName);
    return new Formal(pos, return_type, ret_id);
}

bool check_immutable(string classname)
{
    // cout<<"check_immutable "+classname<<endl;
    if(classname.length()<10) return false;
    const string _immutable="_Immutable";
    for(int i=1;i<=10;i++)
    {
        if(classname[classname.length()-i]!=_immutable[10-i]) return false;
    }
    return true;
}

} // namespace

void AST_Name_Map_Visitor::visit(Program* node) {
#ifdef DEBUG
    std::cout << "Visiting Program" << std::endl;
#endif
    if (node == nullptr) {
         return;
    }

    // Pre-register all class names so extends relations work even if parent is declared later.
    if (node->cdl != nullptr) {
        for (auto cl : *(node->cdl)) {
            if (cl == nullptr || cl->id == nullptr) {
                continue;
            }
            if (!name_maps->add_class(cl->id->id)) {
                fail_with_msg("duplicate class declaration: " + cl->id->id, cl);
            }
        }
    }

    if (node->main != nullptr) {
        node->main->accept(*this);
    }
    if (node->cdl != nullptr) {
        for (auto cl : *(node->cdl)) {
            cl->accept(*this);
        }
    }
}

